import{_ as a,a as r,b as d}from"./chunks/14-chat-settings.BQGgwFPB.js";import{_ as e}from"./chunks/06-chat-first-message.BgaA9QkL.js";import{_ as i,o as n,c as o,a2 as l}from"./chunks/framework.z3u3TMv0.js";const f=JSON.parse('{"title":"聊天","description":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。","frontmatter":{"title":"聊天","description":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"聊天 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 聊天与会话：开聊、流式回复、续写重生成、气泡操作；手机上的 AI 角色扮演对话主界面。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/chat"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/chat"}]]},"headers":[],"relativePath":"manual/chat.md","filePath":"manual/chat.md","lastUpdated":1787132882000}'),s={name:"manual/chat.md"};function h(c,t,p,m,u,_){return n(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h1><p>路径：底部 Tab <strong>聊天</strong>；对话页为单会话主界面。</p><h2 id="会话列表" tabindex="-1">会话列表 <a class="header-anchor" href="#会话列表" aria-label="Permalink to &quot;会话列表&quot;">​</a></h2><p><img src="'+a+'" alt="聊天列表"></p><ul><li>搜索、置顶、克隆、删除会话。</li><li>可导出 / 导入<strong>聊天存档</strong>（见 <a href="./backup">备份与存档</a>）。</li></ul><h2 id="对话页常用操作" tabindex="-1">对话页常用操作 <a class="header-anchor" href="#对话页常用操作" aria-label="Permalink to &quot;对话页常用操作&quot;">​</a></h2><p><img src="'+e+'" alt="对话页"></p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>发送</td><td>用户消息 → 请求模型 → 流式或完整显示回复</td></tr><tr><td>附件图</td><td>输入区加号 → 相册 / 拍照（需模型或识图流程支持）。普通附图会进聊天；若本聊开了「回复图片」，智能/关键词仍可触发出图，附图当风格参考。若输入是 <code>/imagine …</code>，附图只作生图参考，不会当成用户消息发出</td></tr><tr><td><code>/imagine</code></td><td>斜杠生图：主模型先分析是否与对话有关、要不要角色/用户参考，再去生图。张数仅此项读取生图设置。失败会留下气泡，可点重试</td></tr><tr><td>续写</td><td>在当前助手回复末尾继续生成</td></tr><tr><td>重生成</td><td>替换最近助手回复（以 UI 为准）</td></tr><tr><td>智能回复</td><td>生成建议填入输入框，不直接变成助手消息</td></tr><tr><td>取消</td><td>取消进行中的生成</td></tr><tr><td>重新开始</td><td>清空并按开场白重开</td></tr></tbody></table><p>开场白若有多条，开聊时可选择。</p><h2 id="气泡菜单" tabindex="-1">气泡菜单 <a class="header-anchor" href="#气泡菜单" aria-label="Permalink to &quot;气泡菜单&quot;">​</a></h2><p><img src="'+r+'" alt="气泡菜单"></p><p>长按或菜单：复制、编辑、隐藏、删除等。隐藏消息通常不再展示（对上下文的影响以实现为准）。</p><h2 id="聊天设置-按会话" tabindex="-1">聊天设置（按会话） <a class="header-anchor" href="#聊天设置-按会话" aria-label="Permalink to &quot;聊天设置（按会话）&quot;">​</a></h2><p>入口：对话页右上角或设置入口 → <strong>聊天设置</strong>。</p><p><img src="'+d+'" alt="会话设置"></p><table tabindex="0"><thead><tr><th>子项（文案以 App 为准）</th><th>作用</th></tr></thead><tbody><tr><td>角色详情</td><td>查看本聊角色快照 / 导出等</td></tr><tr><td>用户身份</td><td>跟随默认人设或指定</td></tr><tr><td>语言模型</td><td>跟随默认语言模型或指定连接 / 参数</td></tr><tr><td>生图模型</td><td>跟随默认生图，或单独选连接、生图设置与关键词规则</td></tr><tr><td>正则</td><td>多选全局正则组；<strong>空选 = 关闭</strong></td></tr><tr><td>世界书</td><td>多选全局世界书；<strong>空选 = 不注入</strong></td></tr><tr><td>变量管理</td><td>本聊 / 全局宏变量</td></tr><tr><td>前端渲染</td><td>HTML / 脚本相关开关</td></tr><tr><td>识图与显示 / 背景</td><td>识图（图片描写、识人、历史原图深度）与聊天外观</td></tr><tr><td>导出存档</td><td>导出本聊 ZIP</td></tr></tbody></table><h2 id="出错时" tabindex="-1">出错时 <a class="header-anchor" href="#出错时" aria-label="Permalink to &quot;出错时&quot;">​</a></h2><p>气泡错误态可打开 <strong>查看详情</strong>，对照 <a href="./errors">错误代码排错</a>。斜杠生图失败会留在原气泡上，点重试即可再生成。</p>',18)])])}const I=i(s,[["render",h]]);export{f as __pageData,I as default};
